<h1><?= te('Screening questionnaire & contacts') ?></h1><form class="card" method="get"><label><?= te('Application') ?><select name="application_id"><?php foreach($applications as $a): ?><option value="<?= (int)$a['id'] ?>" <?= $applicationId===(int)$a['id']?'selected':'' ?>><?= e($a['title']) ?></option><?php endforeach; ?></select></label><button class="btn"><?= te('Open') ?></button></form>
<?php if(!$own): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="question"><input type="hidden" name="application_id" value="<?= $applicationId ?>"><h2><?= te('Project screening questions') ?></h2><label><?= te('Question') ?><textarea name="question" required maxlength="500"></textarea></label><label><input type="checkbox" name="required" checked style="width:auto"> <?= te('Required before offer') ?></label><button class="btn"><?= te('Add question') ?></button></form><?php endif; ?>
<?php if($application): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="answers"><input type="hidden" name="application_id" value="<?= $applicationId ?>"><h2><?= e($application['full_name'].' · '.$application['title']) ?></h2><?php foreach($questions as $q): ?><label><?= e($q['question']) ?><?= $q['required']?' *':'' ?><textarea name="answer[<?= (int)$q['id'] ?>]" maxlength="4000"><?= e($answers[$q['id']]??'') ?></textarea></label><?php endforeach; ?><button class="btn"><?= te('Save answers') ?></button></form>
<?php if(!$own): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="contact"><input type="hidden" name="application_id" value="<?= $applicationId ?>"><h2><?= te('Record call or interview') ?></h2><select name="kind"><?php foreach(['call','email','interview','note'] as $kind): ?><option value="<?= e($kind) ?>"><?= te(ucfirst($kind)) ?></option><?php endforeach; ?></select><label><?= te('Outcome') ?><input name="outcome" required maxlength="190"></label><label><?= te('Notes') ?><textarea name="note" maxlength="4000"></textarea></label><label><?= te('Follow-up at') ?><input type="datetime-local" name="follow_up_at"></label><button class="btn"><?= te('Save contact') ?></button></form><div class="card"><h2><?= te('Contact history') ?></h2><?php foreach($contacts as $c): ?><p><?= e($c['created_at'].' · '.$c['name'].' · '.$c['kind'].' · '.$c['outcome']) ?></p><p><?= e($c['note']) ?></p><p><?= e($c['follow_up_at']) ?></p><?php endforeach; ?></div><?php endif; ?><?php endif; ?>
